import importlib.util
import os
from pathlib import Path
import tempfile
import unittest


PATH = Path(__file__).resolve().parents[1] / 'intl_source_identities.py'
SPEC = importlib.util.spec_from_file_location('intl_source_identities', PATH)
MODULE = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(MODULE)


class SourceIdentityPreflight(unittest.TestCase):
    def fixture(self, directory):
        root = Path(directory)
        scripts = root / 'scripts'
        scripts.mkdir()
        # The dependent recipe binds its producer's actual generated bytes.
        template = '''from pathlib import Path
import sys
root = Path(__file__).resolve().parents[1]
expected = EXPECTED
output = root / OUTPUT
if '--check' in sys.argv:
    raise SystemExit(0 if output.exists() and output.read_bytes() == expected else 1)
output.write_bytes(expected)
'''
        (root / 'source').write_bytes(b'new source')
        for name, expression, output in [
            ('producer.py', "(root / 'source').read_bytes()", 'identity'),
            ('dependent.py', "(root / 'identity').read_bytes() + b' bound'", 'consumer'),
        ]:
            (scripts / name).write_text(template.replace('EXPECTED', expression)
                                       .replace('OUTPUT', repr(output)))
        return root, ('producer.py', 'dependent.py')

    def test_check_rejects_stale_producer_and_dependent_without_writing(self):
        with tempfile.TemporaryDirectory() as directory:
            root, recipes = self.fixture(directory)
            (root / 'identity').write_bytes(b'old source')
            results = MODULE.refresh(root, recipes)
            self.assertEqual([child.returncode for _, child in results], [1, 1])
            self.assertEqual((root / 'identity').read_bytes(), b'old source')
            self.assertFalse((root / 'consumer').exists())

    def test_write_refreshes_dependency_chain_then_all_checks_pass(self):
        with tempfile.TemporaryDirectory() as directory:
            root, recipes = self.fixture(directory)
            self.assertTrue(all(child.returncode == 0 for _, child in
                                MODULE.refresh(root, recipes, write=True)))
            self.assertEqual((root / 'consumer').read_bytes(), b'new source bound')
            self.assertTrue(all(child.returncode == 0 for _, child in
                                MODULE.refresh(root, recipes)))

    def test_failed_producer_never_runs_dependent_writer(self):
        with tempfile.TemporaryDirectory() as directory:
            root, recipes = self.fixture(directory)
            (root / 'scripts' / recipes[0]).write_text('raise SystemExit(7)\n')
            results = MODULE.refresh(root, recipes, write=True)
            self.assertEqual(len(results), 1)
            self.assertEqual(results[0][1].returncode, 7)
            self.assertFalse((root / 'consumer').exists())

    def test_current_outputs_keep_their_bytes_inodes_and_timestamps(self):
        with tempfile.TemporaryDirectory() as directory:
            root, recipes = self.fixture(directory)
            MODULE.refresh(root, recipes, write=True)
            before = {}
            for name in ('identity', 'consumer'):
                path = root / name
                os.utime(path, ns=(1234567890123456789, 1234567890123456789))
                before[name] = (path.read_bytes(), path.stat().st_ino,
                                path.stat().st_mtime_ns)
            results = MODULE.refresh(root, recipes, write=True)
            self.assertEqual([child.returncode for _, child in results], [0, 0])
            for name, identity in before.items():
                path = root / name
                self.assertEqual((path.read_bytes(), path.stat().st_ino,
                                  path.stat().st_mtime_ns), identity)

    def test_stale_dependent_refreshes_without_touching_its_current_producer(self):
        with tempfile.TemporaryDirectory() as directory:
            root, recipes = self.fixture(directory)
            MODULE.refresh(root, recipes, write=True)
            producer = root / 'identity'
            os.utime(producer, ns=(1234567890123456789, 1234567890123456789))
            before = (producer.stat().st_ino, producer.stat().st_mtime_ns)
            (root / 'consumer').write_bytes(b'stale output')
            results = MODULE.refresh(root, recipes, write=True)
            self.assertEqual([child.returncode for _, child in results], [0, 0])
            self.assertEqual((root / 'consumer').read_bytes(), b'new source bound')
            self.assertEqual((producer.stat().st_ino, producer.stat().st_mtime_ns),
                             before)
            self.assertTrue(all(child.returncode == 0 for _, child in
                                MODULE.refresh(root, recipes)))


if __name__ == '__main__':
    unittest.main()
